from __future__ import annotations

import json
import math
import re
import uuid
from urllib.error import HTTPError, URLError
from urllib.parse import urlencode
from urllib.request import Request, urlopen

from django.conf import settings
from django.core.exceptions import ImproperlyConfigured

from .base import BaseOTPProvider, OTPDeliveryResult


class MSG91OTPProvider(BaseOTPProvider):
    # Deliver the OTP generated by Chokher Alo through MSG91 SendOTP V5.

    provider_name = "msg91"

    def _required_setting(self, name: str) -> str:
        value = str(getattr(settings, name, "") or "").strip()
        if not value:
            raise ImproperlyConfigured(
                f"{name} must be configured when using MSG91OTPProvider."
            )
        return value

    @staticmethod
    def _mobile_for_msg91(phone_number: str) -> str:
        digits = re.sub(r"\D", "", str(phone_number))

        if len(digits) == 10:
            digits = "91" + digits

        if len(digits) != 12 or not digits.startswith("91"):
            raise ValueError(
                "MSG91OTPProvider expects an Indian phone number."
            )

        return digits

    def send(
        self,
        *,
        phone_number: str,
        code: str,
        purpose: str,
    ) -> OTPDeliveryResult:
        del purpose

        auth_key = self._required_setting("MSG91_AUTH_KEY")
        template_id = self._required_setting("MSG91_TEMPLATE_ID")
        endpoint = str(
            getattr(
                settings,
                "MSG91_OTP_ENDPOINT",
                "https://control.msg91.com/api/v5/otp",
            )
        ).strip()
        timeout = int(getattr(settings, "MSG91_TIMEOUT_SECONDS", 10))

        mobile = self._mobile_for_msg91(phone_number)

        ttl_seconds = int(
            getattr(settings, "PHONE_OTP_TTL_SECONDS", 300)
        )
        otp_expiry_minutes = max(
            1,
            math.ceil(ttl_seconds / 60),
        )

        query = urlencode(
            {
                "template_id": template_id,
                "mobile": mobile,
                "otp": code,
                "otp_length": len(code),
                "otp_expiry": otp_expiry_minutes,
            }
        )

        request = Request(
            f"{endpoint}?{query}",
            data=b"{}",
            method="POST",
            headers={
                "authkey": auth_key,
                "accept": "application/json",
                "content-type": "application/json",
            },
        )

        try:
            with urlopen(request, timeout=timeout) as response:
                raw = response.read().decode("utf-8", errors="replace")
                status = response.status
        except HTTPError as exc:
            try:
                exc.read()
            except Exception:
                pass
            raise RuntimeError(
                f"MSG91 rejected the OTP request with HTTP {exc.code}."
            ) from exc
        except URLError as exc:
            raise RuntimeError(
                "MSG91 could not be reached."
            ) from exc

        if status < 200 or status >= 300:
            raise RuntimeError(
                f"MSG91 returned unexpected HTTP status {status}."
            )

        try:
            payload = json.loads(raw) if raw else {}
        except json.JSONDecodeError as exc:
            raise RuntimeError(
                "MSG91 returned an invalid JSON response."
            ) from exc

        response_type = str(payload.get("type", "")).lower()
        if response_type and response_type != "success":
            raise RuntimeError(
                "MSG91 rejected the OTP delivery request."
            )

        message_id = (
            payload.get("request_id")
            or payload.get("message")
            or f"msg91-{uuid.uuid4()}"
        )

        return OTPDeliveryResult(message_id=str(message_id))
